#!/bin/bash
# Download all remaining Aral Sea NISAR data (track 107D) into ./nisar_raw/
#   gunw/ : 18 interferogram files (coherence) for all 9 date pairs, North + South frames  (~41 GB)
#   gcov/ : 18 backscatter files for the 6 dates not yet downloaded (3 Jul-7 Oct)          (~33 GB)
# Needs ~/.netrc with your Earthdata login. Safe to re-run: finished files are skipped, partial ones resume.
set -u
cd "$(dirname "$0")"
[ -f ~/.netrc ] || { echo "Missing ~/.netrc (Earthdata login). See setup notes."; exit 1; }
mkdir -p nisar_raw/gunw nisar_raw/gcov
COOK=~/.urs_cookies

fetch () {  # $1 = URL, $2 = folder
  local url="$1" f="$2/$(basename "$1")" try
  for try in 1 2 3 4 5; do
    if curl -sS -L -n -b "$COOK" -c "$COOK" -C - --retry 3 --retry-delay 10 -o "$f" "$url"; then
      touch "$f.done"; echo "done  $(basename "$f") ($(du -h "$f" | cut -f1))"; return 0
    fi
    echo "retry $try  $(basename "$f")"; sleep 15
  done
  echo "FAILED $(basename "$f") - re-run the script later"
}
export -f fetch
export COOK

dl () {  # $1 = folder, URL list on stdin
  export DIR="$1"
  while read -r url; do
    [ -z "$url" ] && continue
    if [ -f "$DIR/$(basename "$url").done" ]; then echo "skip  $(basename "$url")" >&2; continue; fi
    echo "$url"
  done | xargs -P3 -n1 bash -c 'fetch "$0" "$DIR"'
}

